<?php
declare(strict_types=1);
session_start();
$root=dirname(__DIR__,3);
$cfg=require $root.'/config.php';
date_default_timezone_set($cfg['timezone']??'America/Argentina/Buenos_Aires');
$db=new PDO('mysql:host='.$cfg['db_host'].';dbname='.$cfg['db_name'].';charset=utf8mb4',$cfg['db_user'],$cfg['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
if(empty($_SESSION['user'])){header('Location:index.php');exit;}
$quotes=$db->query("SELECT q.*,p.project_number,p.name project_name,c.business_name FROM quotes q JOIN projects p ON p.id=q.project_id JOIN clients c ON c.id=p.client_id ORDER BY q.quote_date DESC,q.id DESC")->fetchAll();
$projects=$db->query("SELECT p.id,p.project_number,p.name,c.business_name FROM projects p JOIN clients c ON c.id=p.client_id ORDER BY p.id DESC")->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Presupuestos · Punto ERP</title><style>:root{--o:#ff6702;--dark:#171b20;--ink:#27303b;--muted:#6e7781;--line:#e1e5e9;--bg:#f4f6f8;--sidebar:270px}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.45 system-ui}.sidebar{position:fixed;inset:0 auto 0 0;width:var(--sidebar);padding:28px 18px;background:var(--dark);color:#fff}.brand{font-size:22px;font-weight:800;padding:0 12px 28px;border-bottom:1px solid #ffffff18}.brand i{color:var(--o);font-style:normal}.nav{display:flex;flex-direction:column;gap:5px;padding:24px 0}.nav a{padding:11px 13px;border-radius:9px;color:#d8dde3;text-decoration:none;font-weight:600}.nav a.active{background:var(--o);color:#fff}.main{margin-left:var(--sidebar);padding:32px 4%}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:22px;margin-bottom:18px}.row{display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap}.btn{display:inline-block;border:0;border-radius:8px;padding:10px 15px;background:var(--o);color:#fff;text-decoration:none;font-weight:700}.muted{color:var(--muted)}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px 9px;border-bottom:1px solid var(--line)}th{font-size:12px;text-transform:uppercase;color:var(--muted)}select{padding:10px;border:1px solid #cbd1d7;border-radius:8px}@media(max-width:900px){.sidebar{position:static;width:auto}.main{margin-left:0;padding:22px 18px}}</style></head><body><aside class="sidebar"><div class="brand"><i>●</i> Punto ERP</div><nav class="nav"><a href="index.php">Panel general</a><a href="?a=clients">Clientes</a><a href="?a=partners">Arquitectos y constructoras</a><a href="?a=products">Productos</a><a href="?a=projects">Proyectos</a><a class="active" href="?a=quotes">Presupuestos</a><a href="?a=receipts">Recibos y pagos</a><?php if(($_SESSION['user']['role']??'')==='admin'):?><a href="?a=users">Perfiles y usuarios</a><?php endif;?></nav></aside><main class="main"><div class="row"><div><h1>Presupuestos</h1><p class="muted">Listado general de presupuestos por proyecto.</p></div><form method="get"><input type="hidden" name="a" value="new_quote"><select name="project_id" required><option value="">Seleccionar proyecto…</option><?php foreach($projects as $p):?><option value="<?=e($p['id'])?>"><?=e($p['project_number'].' · '.$p['name'].' · '.$p['business_name'])?></option><?php endforeach;?></select> <button class="btn">Nuevo presupuesto</button></form></div><div class="card"><div style="overflow:auto"><table><thead><tr><th>Fecha</th><th>Proyecto</th><th>Cliente</th><th>Versión</th><th>Tipo</th><th>Estado</th><th>Total</th></tr></thead><tbody><?php if(!$quotes):?><tr><td colspan="7" class="muted">Todavía no hay presupuestos cargados.</td></tr><?php endif;?><?php foreach($quotes as $q):?><tr><td><?=e($q['quote_date'])?></td><td><a href="?a=project&id=<?=e($q['project_id'])?>"><?=e($q['project_number'].' · '.$q['project_name'])?></a></td><td><?=e($q['business_name'])?></td><td>v<?=e($q['version_no'])?></td><td><?=e($q['quote_families']?:'—')?></td><td><?=e($q['status'])?></td><td><?=number_format((float)$q['total'],2,',','.')?></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>
